test('P2 canonical Merkle tree authenticates all rows and rejects arbitrary split',async()=>{const v=vector('index-signature'),rows=Array.from({length:300},(_,i)=>({...v.row,entityKey:i.toString(16).padStart(4,'0')+'0'.repeat(60)})),a=buildTree(scope,rows),b=buildTree(scope,[...rows].reverse());expect(a.oid).toBe(b.oid);expect(await readTree(scope,a.oid,async id=>a.nodes.get(id)!)).toEqual(rows);const root=parseCanonicalJson(a.bytes);root.children[0].count++;const raw=jsonBytes(root);await expect(readTree(scope,objectOid('tree',raw),async id=>id===objectOid('tree',raw)?raw:a.nodes.get(id)!)).rejects.toThrow('invalid_schema');});
