test('P2 native adapter binds the same nonce to one final-AAD encryption',async()=>{
 let encryptions=0;const port=createSyncV2Crypto(async<T>(method:string,args:any):Promise<T>=>{
  const raw=(name:string)=>Buffer.from(args[name],'base64');
  if(method==='crypto.random')return {bytesBase64:randomBytes(args.bytes).toString('base64')} as T;
  if(method==='crypto.hkdfSha256')return {keyBase64:Buffer.from(await crypto.hkdf(raw('inputBase64'),raw('saltBase64'),raw('infoBase64'))).toString('base64')} as T;
  if(method==='crypto.v2.encrypt'){encryptions++;const header=parseCanonicalJson(raw('aadBase64'));expect(unb64(header.nonce)).toEqual(new Uint8Array(raw('nonceBase64')));return {ciphertextBase64:Buffer.from(await crypto.encrypt(raw('keyBase64'),raw('nonceBase64'),raw('dataBase64'),raw('aadBase64'))).toString('base64')} as T;}
  if(method==='crypto.aesGcmDecrypt')return {dataBase64:Buffer.from(await crypto.decrypt(raw('keyBase64'),raw('nonceBase64'),raw('ciphertextBase64'),raw('aadBase64'))).toString('base64')} as T;
  throw Error('unexpected native method');
 });const c=vector('envelope').cases[0],i=c.input,result=await sealV2(port,unhex(i.idKeyHex),unhex(i.contentKeyHex),scope,'meta',1,unhex(i.plainHex));expect(encryptions).toBe(1);expect(hex((await openV2(port,unhex(i.idKeyHex),unhex(i.contentKeyHex),scope,result.oid,result.bytes)).plain)).toBe(i.plainHex);
});

