test('P2 R05 negative sort survives projection sealed publication authenticated read and cached republish',async()=>{
 const server=new SyntheticIndexBackend(),f=await publishingFixture(server),db=new SqlFixture();try{
  const value={bookId:'a'.repeat(64),chapterIndex:1,isRead:false,readingProgress:.125,readingPositionBytes:0,readingPositionContentHash:'',readingPositionChangedAt:0,sourceDeviceId:'',favoriteSaved:true,favoriteChangedAt:1,favoriteSortOrder:-1,watchLaterSaved:false,watchLaterChangedAt:2,watchLaterSortOrder:-Number.MAX_SAFE_INTEGER},original=structuredClone(value);
  await f.store.beginScan({...binding,schema:'r05-i53'});await f.store.scanPage({page:async()=>({rows:[{kind:'book-reading',logicalId:value.bookId+':1',value}],after:'done',done:true}),changed:async()=>[]});await f.publisher.prepare('a'.repeat(32),'key',{commitOid:null,revision:'0'},'c'.repeat(32));await f.publisher.flush();
  const store=db.store();await store.initialize();const reader=new WatchCloudIndex(store,f.http,crypto,{id:idKey,content:Buffer.alloc(32,0x22),version:1},async deviceId=>({deviceId,keyId:'b'.repeat(32),publicKey:b64(publicBytes)}),async()=>{},()=>100);expect((await reader.pull(server.window())).bodyReads).toBe(0);const current=await store.readState(),rows=await store.cloudRows(current.cloud.current.treeRoot),reading=rows.find(r=>r.meta.kind==='book-reading');expect(reading.state.payload.favoriteSortOrder).toBe(-1);expect(reading.state.payload.watchLaterSortOrder).toBe(-Number.MAX_SAFE_INTEGER);expect(fromWire('book-reading',reading.meta.payload,reading.state.payload)).toEqual(original);
  await store.beginScan(binding);await store.scanPage({page:async()=>({rows:[],after:'done',done:true}),changed:async()=>[]});const cached=new WatchIndexPublisher(store,f.http,crypto,{id:idKey,content:Buffer.alloc(32,0x22),version:1},()=>100);await cached.prepare('a'.repeat(32),'key',{commitOid:server.account.commitOid,revision:'1'},'d'.repeat(32));await cached.flush();expect(server.events).toBe(2);const latest=parseCanonicalJson(server.objects.get(server.account.commitOid)!),latestRows=await readTree(scope,latest.body.treeRoot,async id=>server.objects.get(id)!);expect(latestRows.find(r=>r.entityKey===reading.row.entityKey).stateOid).toBe(reading.row.stateOid);expect(value).toEqual(original);
 }finally{f.db.close();db.close();}
});

test('P3 C10 P2 double CAS publishes recipe IndexRow without availability',async()=>{
 const server=new SyntheticIndexBackend(),f=await publishingFixture(server),receiverDb=new SqlFixture();
 try{
  const manifest={bodyRevision:'f'.repeat(32),promiseId:null,recipeOid:'recipe:sha256:'+'e'.repeat(64),opaqueContentId:'d'.repeat(64),contentBytes:100000};
  const publisher=new WatchIndexPublisher(f.store,f.http,crypto,{id:idKey,content:Buffer.alloc(32,0x22),version:1},()=>100,async()=>manifest);
  await publisher.prepare('a'.repeat(32),'key',{commitOid:null,revision:'0'},'c'.repeat(32));await publisher.flush();
  const store=receiverDb.store();await store.initialize();const reader=new WatchCloudIndex(store,f.http,crypto,{id:idKey,content:Buffer.alloc(32,0x22),version:1},async deviceId=>({deviceId,keyId:'b'.repeat(32),publicKey:b64(publicBytes)}),async()=>{},()=>100);
  await reader.pull(server.window());const row=(await store.cloudRows((await store.readState()).cloud.current.treeRoot))[0].row;
  for(const key of ['bodyRevision','promiseId','recipeOid','opaqueContentId','contentBytes'] as const)expect(row[key]).toBe(manifest[key]);
  expect(server.events).toBe(1);expect(server.calls['/account/publish']).toBe(1);expect(server.calls['/availability/check']??0).toBe(0);
 }finally{f.db.close();receiverDb.close();}
});

for(const checkpointLoss of [false,true])test('P3AR R04 P2 control helper consumes replay budget before PUT '+(checkpointLoss?'with lost checkpoint reply':'with lost ACK'),async()=>{
 const server=new SyntheticIndexBackend(),db=new SqlFixture(),store=db.store(),send=server.request.bind(server);let pause=true,repair=false;
 await store.initialize();await store.beginScan(binding);await store.scanPage({page:async()=>({rows:[{kind:'note',logicalId:'repair-note',value:{...noteValue('repair-note'),markdown:'x'.repeat(180000)},addedAtMillis:50}],after:'done',done:true}),changed:async()=>[]});
 server.request=async r=>{const path=decodeURIComponent(new URL(r.url).pathname);const out=await send(r);if(pause&&path.includes('/objects/state:')&&path.endsWith('/parts/65536')){pause=false;db.afterCommit=true;}if(repair&&path.includes('/objects/state:')&&path.endsWith('/parts/65536'))throw Error('lost_control_repair_ack');return out;};
 const http=new SyncV2Http(server,'http://localhost:3000',scope,async()=>({accessToken:'synthetic',legacyDeviceId:'approved-old',userId:'00000000-0000-0000-0000-000000000001',scope}),true,serverPin()),make=()=>new WatchIndexPublisher(store,http,crypto,{id:idKey,content:Buffer.alloc(32,0x22),version:1},()=>100);
 try{await make().prepare('a'.repeat(32),'synthetic-key',{commitOid:null,revision:'0'},'d'.repeat(32));await expect(make().flush()).rejects.toThrow('injected_after_commit');db.afterCommit=false;const id=[...server.partials.keys()].find(id=>id.startsWith('state:'))!,original=server.partials.get(id)!.slice(),before=server.calls['/objects/'+id+'/parts/65536']!;repair=true;
  server.partials.set(id,original.slice(0,65536));db.afterCommit=checkpointLoss;await expect(make().flush()).rejects.toThrow(checkpointLoss?'injected_after_commit':'lost_control_repair_ack');db.afterCommit=false;server.partials.set(id,original.slice(0,65536));await expect(make().flush()).rejects.toThrow('offset_conflict');expect(server.calls['/objects/'+id+'/parts/65536']!-before).toBe(checkpointLoss?0:1);expect((await store.uploadReceipt('d'.repeat(32),id)).durableOffset).toBe(131072);expect(server.events).toBe(0);
 }finally{db.close();}
});
test('C29 relay result poll leaves unknown journals intact and accepts cloud success without new writes',async()=>{
 const server=new SyntheticIndexBackend(),f=await publishingFixture(server);
 try{await f.publisher.prepare('a'.repeat(32),'key',{commitOid:null,revision:'0'},'c'.repeat(32));const before=canonical(await f.store.readState());
  expect(await f.publisher.reconcileRelayResult()).toBeNull();expect(canonical(await f.store.readState())).toBe(before);expect(server.calls['/objects/reserve']??0).toBe(0);expect(server.calls['/account/publish']??0).toBe(0);
  server.losePublish=true;await expect(f.publisher.flush()).rejects.toThrow('synthetic_response_lost');const calls={...server.calls},result=await f.publisher.reconcileRelayResult();expect(result.account.commitOid).toBe(server.account.commitOid);expect(server.calls['/account/publish']).toBe(calls['/account/publish']);expect(server.calls['/objects/reserve']).toBe(calls['/objects/reserve']);expect((await f.store.readState()).cloud.pendingPublish).toBeNull();
 }finally{f.db.close();}
});
